html:
{% set company = frappe.db.get_default("company") or frappe.db.get_single_value("Global Defaults", "default_company") %}
{% set company_logo = frappe.db.get_value("Company", company, "company_logo") if company else "" %}
{% set customer_name = frappe.db.get_value("Job Order", doc.job_order, "customer_name") if doc.job_order else "" %}

<style>
  @page {
    size: A4;
    margin: 8mm;
  }

  body {
    margin: 0;
    padding: 0;
    font-family: Arial, sans-serif;
    color: #000;
  }

  .qc-page {
    width: 100%;
    min-height: 277mm;
    box-sizing: border-box;
    font-family: Arial, sans-serif;
    color: #000;
    font-size: 12px;
  }

  .qc-title {
    text-align: center;
    font-size: 19px;
    font-weight: 700;
    line-height: 1;
    margin: 0 0 3px 0;
    text-transform: uppercase;
  }

  .qc-main {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    border: 1px solid #000;
  }

  .qc-main td,
  .qc-main th {
    border: 1px solid #000;
    vertical-align: top;
  }

  .company-block { padding: 6px 7px 4px 7px; }

  .company-logo-row { margin-bottom: 4px; } .company-logo-row img { width: 130px; height: 110px; object-fit: contain; display: block; }

  .company-name {
    font-size: 14px;
    font-weight: 700;
    line-height: 1.15;
    margin-bottom: 4px;
    text-transform: uppercase;
  }

  .company-line {
    font-size: 12px;
    line-height: 1.25;
  }

  .doc-info {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .doc-info td {
    border-left: none;
    border-right: none;
    border-top: none;
    border-bottom: 1px solid #000;
    padding: 3px 5px;
    height: 26px;
    font-size: 12px;
    line-height: 1.15;
  }

  .doc-info tr:last-child td {
    border-bottom: none;
  }

  .section-title {
    background: #f0f0f0;
    font-weight: 700;
    padding: 3px 6px;
    font-size: 12px;
    text-transform: uppercase;
    border: 1px solid #000;
    border-top: none;
  }

  .detail-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .detail-table td {
    border: 1px solid #000;
    padding: 4px 6px;
    font-size: 12px;
    line-height: 1.3;
    vertical-align: top;
  }

  .detail-table .label {
    width: 30%;
    font-weight: 400;
    background: #fafafa;
  }

  .detail-table .value {
    font-weight: 700;
  }

  .status-approved { color: #067d3f; }
  .status-rejected { color: #b3261e; }
  .status-pending { color: #a15c00; }

  .remarks-box {
    border: 1px solid #000;
    border-top: none;
    padding: 6px;
    min-height: 60px;
    font-size: 12px;
    white-space: pre-wrap;
  }

  .bottom-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    border-left: 1px solid #000;
    border-right: 1px solid #000;
    border-bottom: 1px solid #000;
    margin-top: 10px;
  }

  .bottom-table td {
    border: 1px solid #000;
    padding: 6px 6px;
    height: 48px;
    vertical-align: top;
    font-size: 12px;
  }

  .sign-cell {
    text-align: right;
  }

  .sign-company {
    font-size: 12px;
    font-weight: 700;
    margin-bottom: 25px;
  }

  .sign-title {
    font-size: 11px;
  }

  .generated {
    text-align: center;
    font-size: 12px;
    margin-top: 8px;
  }

  @media print {
    .qc-page {
      page-break-after: avoid;
    }
  }
</style>

<div class="qc-page">

  <div class="qc-title">QC Report Request</div>

  <table class="qc-main">
    <tr>
      <td style="width:50%;" class="company-block" rowspan="2">
        <div class="company-logo-row">{% if company_logo %}<img src="{{ company_logo }}" alt="Company Logo" width="130" height="110">{% else %}<img src="/files/AP_Logo.webp" alt="Company Logo" width="130" height="110" onerror="this.style.display='none'">{% endif %}</div><div class="company-name">ASIA PETROCHEMICALS LLC OPC</div><div class="company-line">Plot # A 23 B, Al Jazeera Industrial Area</div><div class="company-line">TRN : 100283348900003</div><div class="company-line">Emirate : Ras Al-Khaimah</div><div class="company-line">E-Mail : info@asia-petrochem.com</div>
      </td>

      <td style="width:25%;">
        <table class="doc-info">
          <tr>
            <td>
              <div>QC Report Request No.</div>
              <div class="value">{{ doc.name }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Requested By</div>
              <div class="value">{{ doc.requested_by or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Requested On</div>
              <div class="value">{{ frappe.utils.format_datetime(doc.requested_on) if doc.requested_on else "-" }}</div>
            </td>
          </tr>
        </table>
      </td>

      <td style="width:25%;">
        <table class="doc-info">
          <tr>
            <td>
              <div>Customer</div>
              <div class="value">{{ customer_name or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Job Order</div>
              <div class="value">{{ doc.job_order or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Inspection Type</div>
              <div class="value">{{ doc.inspection_type or "-" }}</div>
            </td>
          </tr>
        </table>
      </td>
    </tr>

    <tr></tr>
  </table>

  <div class="section-title">Source Documents</div>
  <table class="detail-table">
    <tr>
      <td class="label">Security Inspection</td>
      <td class="value">{{ doc.security_inspection or "-" }}</td>
      <td class="label">Delivery Order</td>
      <td class="value">{{ doc.delivery_order or "-" }}</td>
    </tr>
    <tr>
      <td class="label">Security Draft DN</td>
      <td class="value">{{ doc.security_draft_delivery_note or "-" }}</td>
      <td class="label">Loading Delivery Note</td>
      <td class="value">{{ doc.loading_delivery_note or "-" }}</td>
    </tr>
    <tr>
      <td class="label">Batch</td>
      <td class="value">{{ doc.batch or "-" }}</td>
      <td class="label">COA</td>
      <td class="value">{{ doc.coa or "-" }}</td>
    </tr>
  </table>

  <div class="section-title">Inspection Details</div>
  <table class="detail-table">
    <tr>
      <td class="label">Container Number</td>
      <td class="value">{{ doc.container_number or "-" }}</td>
      <td class="label">Vehicle Number</td>
      <td class="value">{{ doc.vehicle_number or "-" }}</td>
    </tr>
    <tr>
      <td class="label">Driver Name</td>
      <td class="value">{{ doc.driver_name or "-" }}</td>
      <td class="label">Batch Number</td>
      <td class="value">{{ doc.batch_number or "-" }}</td>
    </tr>
    <tr>
      <td class="label">Material Description</td>
      <td class="value" colspan="3">{{ doc.material_description or "-" }}</td>
    </tr>
  </table>

  <div class="section-title">QC Status</div>
  <table class="detail-table">
    <tr>
      <td class="label">Status</td>
      <td class="value {% if doc.qc_status == 'Approved' or doc.qc_status == 'Cleared' %}status-approved{% elif doc.qc_status == 'Rejected' %}status-rejected{% else %}status-pending{% endif %}">{{ doc.qc_status or "Pending" }}</td>
      <td class="label">Checked By</td>
      <td class="value">{{ doc.qc_checked_by or "-" }}</td>
    </tr>
    <tr>
      <td class="label">Checked On</td>
      <td class="value" colspan="3">{{ frappe.utils.format_datetime(doc.qc_checked_on) if doc.qc_checked_on else "-" }}</td>
    </tr>
  </table>
  <div class="remarks-box">
    <b>Remarks:</b><br>
    {{ frappe.utils.strip_html(doc.qc_remarks) if doc.qc_remarks else "-" }}
  </div>

  {% if doc.notes %}
  <div class="section-title">Notes</div>
  <div class="remarks-box">{{ frappe.utils.strip_html(doc.notes) }}</div>
  {% endif %}

  <table class="bottom-table">
    <tr>
      <td style="width:50%;">
        QC Cleared / Rejected
      </td>

      <td style="width:50%;" class="sign-cell">
        <div class="sign-company">for ASIA PETROCHEMICALS LLC OPC</div>
        <div class="sign-title">Authorised Signatory</div>
      </td>
    </tr>
  </table>

  <div class="generated">This is a Computer Generated Document</div>

</div>
